document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".alert-toggle").forEach(e=>{e.addEventListener("change",function(){const n=e.getAttribute("data-tool-id");fetch("price_alerts.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({tool_id:n,enable:e.checked})}).then(t=>t.json()).then(t=>{t.success||(alert(t.error||"Something went wrong."),e.checked=!e.checked)})})})});
